def eta(a,b):
 if b<a: return (a-b)/a
 if b>a: return (b-a)/(1-a)
 return 0.
def ur(a,b,wa,wb):
 return min(wb*eta(a,b),wa*eta(b,a))
def metrics(a,b):
 e=.7*a+.3*b-.1
 fnl=max(0,min(1,-2/3+7*a/3))
 fnr=3*b/7
 u=ur(a,b,.35,.15)+ur(fnl,fnr,.15,.35)
 return u,e
betas=[.1,.5,.59,.6,.61,.8,.99]
best={beta:(float('inf'),None) for beta in betas}
xs=[2/7+(3/7)*i/1000 for i in range(1001)]+[.35]
zs=[i/1000 for i in range(1001)]+[2/7,.35]
for a in xs:
 for b in zs:
  u,e=metrics(a,b)
  for beta in betas:
   v=beta*u+(1-beta)*e
   if v<best[beta][0]: best[beta]=(v,(a,b,u,e))
for beta in betas: print('beta',beta,'best',best[beta])
print('feasible error-cap example',metrics(2/7,1/4))
E=.175
bestcap=(float('inf'),None)
for i in range(100001):
 a=2/7+((E+.1)/.7-2/7)*i/100000
 b=max(0,(E+.1-.7*a)/.3)
 u,e=metrics(a,b)
 if u<bestcap[0]: bestcap=(u,(a,b,e))
print('grid at error cap',bestcap)
for x in [.25,.5,.75]:
 psi=.5*eta(x,.5*x)+.5*(1-.5*x)
 print('lemma psi',x,psi)
